/* The handbook app's server (HB1.2, operator 2026-10-28).
 *
 * A SEPARATE Apps Script project from Team Tools: any employee signed in to the
 * org's domain may open it (the deployment's access is the domain; it runs as
 * the deployer, so readers need no access to the spreadsheet). It READS the
 * same Knowledge Base spreadsheet Team Tools publishes the handbook into, and
 * writes nothing — importing and publishing stay in Team Tools' Admin.
 *
 * TWO FILES, one global scope (as in Team Tools):
 *   kb_shared.js  GENERATED by scripts/handbook-sync.mjs — Team Tools'
 *                 handbook readers copied VERBATIM, with every declaration
 *                 they reach. Never edit it: edit web-app/ and run
 *                 `npm run handbook:sync`. CI fails while it differs.
 *   Handbook.js   this file — the ENVIRONMENT the copied code expects (who is
 *                 asking, which spreadsheet, the KB tab, today), and the public
 *                 endpoints the shared reader calls.
 *
 * The copied code calls getEmployeeInfo_, getKbSS_, getOrCreateKbSheet_ and
 * fmtDate_ by those names; this file supplies them, and the sync stops its
 * dependency walk at every name declared here. A Team Tools endpoint the
 * handbook serves is copied under a private name (`tt` + its name + `_`, the
 * sync's RENAMES table) so the public name here decides what the handbook
 * does with it — getReferenceItem, for one, serves handbook sections only.
 *
 * Every public function below (a name that does not end in `_` is reachable
 * by google.script.run — g143) is pinned by name in test/client/run.js.
 *
 * Freshness: this project's script cache is its own, so Team Tools' cache
 * clears never reach it. Everything cached here lives HB_CACHE_TTL seconds
 * (the meta through the copied kbManualMetaCached_, KB_CACHE_TTL — the same
 * five minutes), so a publish in Team Tools shows here within five minutes.
 * Images are cached by content hash and are never stale. */

const HB_KB_SS_PROP = 'HANDBOOK_KB_SS_ID';
const HB_CACHE_TTL = 300;
const HB_PARTS_CACHE_KEY = 'hb_parts_v2:';   // v2 (HB1.3): the answer carries its stamp
const HB_NOT_HERE = 'is not available in the handbook app yet.';

/** HB1.3: the page, with the link's section (`?s=6.9.3`) — the page cannot
 *  read its own address (g107), so the server hands it over. Only a value
 *  shaped like a section number survives; the page resolves it. */
function doGet(e) {
  const t = HtmlService.createTemplateFromFile('index');
  const s = String((e && e.parameter && e.parameter.s) || '').trim();
  t.hbParams = { s: /^[\w.§ -]{1,24}$/.test(s) ? s : '' };
  return t.evaluate()
    .setTitle('UMS Handbook')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1');
}
function include(filename) {
  return HtmlService.createHtmlOutputFromFile(filename).getContent();
}

// ── The environment the copied code expects ─────────────────────────────

/** Who is asking. Any signed-in account the deployment lets in (the domain)
 *  is a reader; nobody is an admin here, so a draft is never served — the
 *  copied readers hide drafts from a caller whose isAdmin is false. */
function getEmployeeInfo_() {
  let email = '';
  try { email = String(Session.getActiveUser().getEmail() || '').trim().toLowerCase(); } catch (e) { email = ''; }
  if (!email) return null;
  return { email: email, isAdmin: false, isManager: false };
}
let _hbKbSS = null;
/** The Knowledge Base spreadsheet, by the HANDBOOK_KB_SS_ID Script Property —
 *  unset is said by name, never a fallback (g122). */
function getKbSS_() {
  if (_hbKbSS) return _hbKbSS;
  const id = String(PropertiesService.getScriptProperties().getProperty(HB_KB_SS_PROP) || '').trim();
  if (!id) throw new Error('The handbook is not set up yet: the ' + HB_KB_SS_PROP + ' Script Property is not set.');
  _hbKbSS = SpreadsheetApp.openById(id);
  return _hbKbSS;
}
/** The KB tab. Team Tools' function of this name CREATES the tab; the
 *  handbook only reads, so a missing tab is an error that names it. */
function getOrCreateKbSheet_() {
  const sheet = getKbSS_().getSheetByName(HB_TT_CONFIG.KB_TAB);
  if (!sheet) throw new Error('The "' + HB_TT_CONFIG.KB_TAB + '" tab is missing from the handbook\'s spreadsheet.');
  return sheet;
}
/** Today in Team Tools' storage timezone, so "recent" means the same day in
 *  both apps (CONFIG.TIMEZONE, copied by the sync). */
function fmtDate_(d) { return Utilities.formatDate(d, HB_TT_CONFIG.TIMEZONE, 'yyyy-MM-dd'); }

/** A JSON value through the script cache in pieces (one cache value holds
 *  100 KB) — the copied search index's chunking constants. null on a miss. */
function hbCacheGetJson_(base) {
  try {
    const cache = CacheService.getScriptCache();
    const n = parseInt(cache.get(base + 'n') || '', 10);
    if (!(n > 0)) return null;
    const keys = [];
    for (let i = 0; i < n; i++) keys.push(base + i);
    const got = cache.getAll(keys);
    if (!keys.every(function (k) { return typeof got[k] === 'string'; })) return null;
    return JSON.parse(keys.map(function (k) { return got[k]; }).join(''));
  } catch (e) { return null; }
}
function hbCachePutJson_(base, value) {
  try {
    const json = JSON.stringify(value), put = {};
    let n = 0;
    for (let at = 0; at < json.length; at += KB_INDEX_CHUNK) put[base + (n++)] = json.substring(at, at + KB_INDEX_CHUNK);
    if (n <= KB_INDEX_MAX_CHUNKS) { put[base + 'n'] = String(n); CacheService.getScriptCache().putAll(put, HB_CACHE_TTL); }
  } catch (e) {}
}

// ── Public endpoints (the shared reader's SHELL NEEDS, plus what's new) ──

function getManualMeta() { return ttGetManualMeta_(); }
function getManualPart(department) { return ttGetManualPart_(department); }
/** Every chapter in one read, cached for HB_CACHE_TTL — every reader asks for
 *  this once per visit, and the answer is the same for all of them (nobody is
 *  an admin here). A refusal or an error is never cached (g129). */
function getManualParts() {
  if (!getEmployeeInfo_()) return { error: 'Not authorized.' };
  const hit = hbCacheGetJson_(HB_PARTS_CACHE_KEY);
  if (hit) return hit;
  const res = ttGetManualParts_();
  if (res && !res.error) {
    res.stamp = hbStamp_(JSON.stringify(res.parts));
    hbCachePutJson_(HB_PARTS_CACHE_KEY, res);
    try { CacheService.getScriptCache().put(HB_PARTS_CACHE_KEY + 'stamp', res.stamp, HB_CACHE_TTL); } catch (e) {}
  }
  return res;
}
/** HB1.3 — what the browser's kept copy of the chapters is checked against:
 *  the stamp of the chapters this server would send now. Cheap while the
 *  parts are cached (one cache read); otherwise it reads them, which the
 *  next getManualParts then serves from the cache. */
function getManualStamp() {
  if (!getEmployeeInfo_()) return { error: 'Not authorized.' };
  let stamp = null;
  try { stamp = CacheService.getScriptCache().get(HB_PARTS_CACHE_KEY + 'stamp'); } catch (e) {}
  if (stamp) return { stamp: stamp };
  const res = getManualParts();
  if (!res || res.error || !res.stamp) return { error: (res && res.error) || 'Could not read the handbook.' };
  try { CacheService.getScriptCache().put(HB_PARTS_CACHE_KEY + 'stamp', res.stamp, HB_CACHE_TTL); } catch (e) {}
  return { stamp: res.stamp };
}
/** PURE — a short, stable fingerprint of a string (FNV-1a over UTF-16 code
 *  units, with the length, hex). Equal chapters give equal stamps. */
function hbStamp_(s) {
  s = String(s);
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return ('0000000' + h.toString(16)).slice(-8) + '-' + s.length.toString(36);
}
function getManualImages(keys) { return ttGetManualImages_(keys); }
function getKbImages(keys) { return ttGetKbImages_(keys); }
/** A cross-reference preview: handbook sections only. A link to an ordinary
 *  Reference article is answered as such — those articles are Team Tools'. */
function getReferenceItem(id) {
  if (!KB_MANUAL_ID_RE.test(String(id || '').trim())) return { error: 'That article is in Team Tools\' Reference, not the handbook.' };
  return ttGetReferenceItem_(id);
}
/** The handbook's recent changes — published sections only, the window Team
 *  Tools' What's new uses. null when nothing changed; {error: true} on a
 *  failed read (g53). */
function getManualRecent() {
  if (!getEmployeeInfo_()) return { error: 'Not authorized.' };
  return kbManualRecentPayload_();
}
/** Not served here (yet): Drive thumbnails (the domain disables Apps Script's
 *  Drive), warehouse distances (a Reference block the handbook does not use),
 *  and section feedback (HB1.4 routes it to each chapter's owner). Each says so
 *  in the shape its caller reads as a failure. */
function kbGetImageData() { return { success: false, error: 'Drive images ' + HB_NOT_HERE }; }
function kbMapDistances() { return { error: 'Distances ' + HB_NOT_HERE }; }
function kbFlagItem() { return { success: false, error: 'Feedback ' + HB_NOT_HERE }; }
